@startuml

class ProjectManager {
}

class Project {
  + startDate : date
  + endDate : date
}

class Team {
}

abstract class WorkProduct {
  + description : string
  + percentComplete : float
}

class Requirement {
  + media : string
  + validateWithUsers()
}

class System {
  + platform : string
  + validateAgainstRequirements()
}

ProjectManager "1" -- "*" Project : manages
ProjectManager "1" -- "*" Team : leads
Project "1" *-- "1..*" Requirement : uses
Project "1" -- "*" System : produces
Requirement extends WorkProduct
System extends WorkProduct

@enduml

